#define MOD 1000000007LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

static ll mod_inv(ll a) {
    return mod_pow(a, MOD - 2);
}

int main(void) {
    int N, M;
    long long L, R;
    if (scanf("%d %d %lld %lld", &N, &M, &L, &R) != 4) return 0;

    /*
      Let F(S) = number of sequences of N nonnegative integers with sum = S
      such that after sorting in non-increasing order, b_M = b_{M+1}.

      Complement:
      b_M > b_{M+1}  <=> there exists a unique threshold t = b_M such that
      at least M elements are >= t, but at most M elements are >= t+1.
      Hence exactly M elements are >= t and the rest are <= t-1.

      For fixed t>=1:
        choose which M positions are the "large" ones: C(N,M)
        write large ones as t + x_i (x_i>=0), small ones as y_j (0<=y_j<=t-1)

      Sum condition:
        sum x_i + sum y_j = S - M t

      Number for fixed t:
        coeff of z^{S-Mt} in (1/(1-z)^M) * (1+z+...+z^{t-1})^{N-M}
      Since (1+...+z^{t-1}) = (1-z^t)/(1-z),
        this equals coeff of z^{S-Mt} in (1-z^t)^{N-M} / (1-z)^N

      Summing over t and then over S<=X, after coefficient extraction and
      hockey-stick:
        G(X) = #complement with sum <= X
             = C(N,M) * sum_{t>=1} sum_{k=0}^{N-M} (-1)^k C(N-M,k)
               C(X - t(M+k) + N, N)
      where terms with negative top are 0.

      Then desired answer for sums in [L,R]:
        total_all(R)-total_all(L-1) - (G(R)-G(L-1))

      total_all(X) = C(X+N, N) for X>=0.
    */

    int K = N - M;

    /* Need factorials up to max(R+N, maybe small N). */
    long long maxV = R + N;
    if (maxV < N) maxV = N;
    int LIM = (int)maxV;

    ll *fact = (ll*)malloc((LIM + 1) * sizeof(ll));
    ll *invfact = (ll*)malloc((LIM + 1) * sizeof(ll));
    fact[0] = 1;
    for (int i = 1; i <= LIM; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[LIM] = mod_inv(fact[LIM]);
    for (int i = LIM; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    auto ll Csmall(long long n, int r) {
        if (r < 0 || n < r || n < 0) return 0;
        return fact[(int)n] * invfact[r] % MOD * invfact[(int)n - r] % MOD;
    }

    ll chooseNM = Csmall(N, M);

    ll *binK = (ll*)malloc((K + 1) * sizeof(ll));
    for (int k = 0; k <= K; k++) binK[k] = Csmall(K, k);

    auto ll total_all(long long X) {
        if (X < 0) return 0;
        return Csmall(X + N, N);
    }

    auto ll G(long long X) {
        if (X < 0) return 0;
        ll ans = 0;
        for (int k = 0; k <= K; k++) {
            int d = M + k;
            if (d <= 0) continue;
            long long Tmax = X / d;
            if (Tmax <= 0) continue;

            ll sum = 0;
            for (long long t = 1; t <= Tmax; t++) {
                long long n = X - t * d + N;
                sum += Csmall(n, N);
                if (sum >= MOD) sum -= MOD;
            }

            ll term = binK[k] * sum % MOD;
            if (k & 1) {
                ans -= term;
                if (ans < 0) ans += MOD;
            } else {
                ans += term;
                if (ans >= MOD) ans -= MOD;
            }
        }
        ans = ans * chooseNM % MOD;
        return ans;
    }

    ll allR = total_all(R);
    ll allL = total_all(L - 1);
    ll badR = G(R);
    ll badL = G(L - 1);

    ll ans = (allR - allL) % MOD;
    if (ans < 0) ans += MOD;
    ans = (ans - ((badR - badL) % MOD)) % MOD;
    if (ans < 0) ans += MOD;

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    free(binK);
    return 0;
}

