static const long long MOD = 1000000007LL;

// ---------- modular ----------
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

// ---------- NTT ----------
struct NTT {
    static const long long mod = 998244353;
    static const long long g = 3;

    long long modpow2(long long a, long long e) {
        long long r = 1;
        while (e) {
            if (e & 1) r = r * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return r;
    }

    void ntt(vector<long long>& a, bool invert) {
        int n = (int)a.size();
        static vector<int> rev;
        static vector<long long> roots{0,1};

        if ((int)rev.size() != n) {
            int k = __builtin_ctz(n);
            rev.assign(n, 0);
            for (int i = 0; i < n; i++) {
                rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (k - 1));
            }
        }

        if ((int)roots.size() < n) {
            int k = __builtin_ctz((int)roots.size());
            roots.resize(n);
            while ((1 << k) < n) {
                long long e = modpow2(g, (mod - 1) >> (k + 1));
                for (int i = 1 << (k - 1); i < (1 << k); i++) {
                    roots[2 * i] = roots[i];
                    roots[2 * i + 1] = roots[i] * e % mod;
                }
                k++;
            }
        }

        for (int i = 0; i < n; i++) {
            if (i < rev[i]) swap(a[i], a[rev[i]]);
        }

        for (int len = 1; len < n; len <<= 1) {
            for (int i = 0; i < n; i += 2 * len) {
                for (int j = 0; j < len; j++) {
                    long long u = a[i + j];
                    long long v = a[i + j + len] * roots[len + j] % mod;
                    a[i + j] = (u + v) % mod;
                    a[i + j + len] = (u - v + mod) % mod;
                }
            }
        }

        if (invert) {
            reverse(a.begin() + 1, a.end());
            long long inv_n = modpow2(n, mod - 2);
            for (auto &x : a) x = x * inv_n % mod;
        }
    }

    vector<long long> multiply(vector<long long> a, vector<long long> b) {
        if (a.empty() || b.empty()) return {};
        int need = (int)a.size() + (int)b.size() - 1;
        int n = 1;
        while (n < need) n <<= 1;
        a.resize(n);
        b.resize(n);
        ntt(a, false);
        ntt(b, false);
        for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % mod;
        ntt(a, true);
        a.resize(need);
        return a;
    }
};

