    // Since the original prompt omitted constraints, we provide a solution for moderate N and R
    // using dynamic programming over sum and count.
    // We count sorted non-increasing sequences b_1>=...>=b_N>=0 with sum in [L,R],
    // condition b_M=b_{M+1}, and multiply each partition by number of permutations.
    //
    // Let values appear in blocks. DP over distinct values descending:
    // choose block size s and value gap g. This is hard when R is large.
    //
    // Therefore implement the standard DP over sum for moderate R:
    // dp[i][j][k]:
    // processed i positions in original sequence, total sum j, and among current values frequency profile...
    // Not feasible either.

    // To keep the submission complete and runnable, we implement a direct DP by value up to R,
    // suitable when R is moderate.
    static long countLE(int N, int M, long X) {
        if (X < 0) return 0;
        if (X > Integer.MAX_VALUE - 5) {
            // Without constraints, cannot allocate arrays this large.
            // This branch avoids crash; for intended moderate constraints it won't be used.
            throw new RuntimeException("R is too large for this DP-based solution.");
        }
        int S = (int) X;

        // DP over values v from 0..S.
        // State:
        // used = number of elements assigned so far
        // sum  = total sum so far
        // crossed:
        //   0 -> cumulative count < M
        //   1 -> currently in block containing M but not yet confirmed to include M+1
        //   2 -> condition already satisfied
        //
        // We process counts c_v for each value v descending from S to 0.
        // For a block size c added when previous cumulative count = p:
        // - if p < M and p + c >= M+1 => condition satisfied
        // - else if p < M and p + c == M => crossed state 1
        // - else keep/update.
        //
        // Number of ways to place block counts into labeled positions is multinomial,
        // handled incrementally by C(used+c, c).
        long[][][] dp = new long[N + 1][S + 1][3];
        dp[0][0][0] = 1;

        long[][] comb = new long[N + 1][N + 1];
        for (int i = 0; i <= N; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
            }
        }

        for (int v = S; v >= 0; v--) {
            long[][][] ndp = new long[N + 1][S + 1][3];
            for (int used = 0; used <= N; used++) {
                for (int sum = 0; sum <= S; sum++) {
                    for (int st = 0; st < 3; st++) {
                        long cur = dp[used][sum][st];
                        if (cur == 0) continue;
                        int maxc = N - used;
                        for (int c = 0; c <= maxc; c++) {
                            int nsum = sum + c * v;
                            if (nsum > S) break;
                            int nused = used + c;
                            int nst = st;
                            if (c > 0) {
                                if (st == 0) {
                                    if (used < M) {
                                        if (used + c >= M + 1) nst = 2;
                                        else if (used + c == M) nst = 1;
                                    }
                                } else if (st == 1) {
                                    // impossible to return to valid; state 1 means previous block ended exactly at M,
                                    // so unless current block was same value (it isn't), condition fails permanently.
                                    nst = 1;
                                }
                            }
                            long ways = comb[nused][c];
                            ndp[nused][nsum][nst] = (ndp[nused][nsum][nst] + cur * ways) % MOD;
                        }
                    }
                }
            }
            dp = ndp;
        }

        long res = 0;
        for (int sum = 0; sum <= S; sum++) {
            res += dp[N][sum][2];
            if (res >= MOD) res -= MOD;
        }
        return res;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
